parameters.jsCode:
// Valida payload UAZAPI e extrai dados (texto ou audio).
// Donos vem do BANCO (giulia_donos) - resolucao no node 'Resolver Dono'.
// Aqui so o mapa de numeros alternativos -> canonico (Thiago tem 2 numeros).
const ALIAS = { '5511964486564': '5511910441709' };

const body = items[0].json.body || items[0].json;
const msg = body.message || body.data || body;

// Ignorar fromMe
const fromMe = msg.fromMe === true || msg.key?.fromMe === true;
if (fromMe) return [];

// Ignorar grupos
const chatId = String(msg.chatid || msg.chatId || msg.key?.remoteJid || '');
if (chatId.includes('@g.us') || chatId.includes('-')) return [];

const senderNumero = chatId.replace(/@.*$/, '').replace(/[^0-9]/g, '');
if (!senderNumero || senderNumero.length < 10) return [];

// Timestamp provisorio em Brasilia - 'Resolver Dono' recalcula no fuso real do dono
const donoCanonGuess = ALIAS[senderNumero] || senderNumero;
// WhatsApp BR pode entregar o JID SEM o nono digito (55 DD 8 digitos) mesmo
// quando o numero cadastrado tem 9 (55 DD 9XXXXXXXX) - e vice-versa.
// Gera a outra forma pro lookup do dono cobrir os dois cadastros.
let donoCanonGuessAlt = '';
if (/^55\d{10}$/.test(donoCanonGuess)) donoCanonGuessAlt = donoCanonGuess.slice(0, 4) + '9' + donoCanonGuess.slice(4);
else if (/^55\d{2}9\d{8}$/.test(donoCanonGuess)) donoCanonGuessAlt = donoCanonGuess.slice(0, 4) + donoCanonGuess.slice(5);
const tzLocal = 'America/Sao_Paulo';
const agoraISO = new Date().toLocaleString('sv-SE', { timeZone: tzLocal }).substring(0, 19);
const messageId = msg.id || msg.messageid || msg.key?.id || '';

// Detectar audio (varios formatos UAZAPI/WA possiveis)
const messageType = String(msg.messageType || msg.type || msg.mediaType || '').toLowerCase();
// UAZAPI tem DOIS formatos de webhook: o classico (msg.audioMessage/imageMessage/
// documentMessage) e o do WhatsApp Web/API nova, onde os dados da midia vem em
// msg.content (objeto com mimetype, fileName, URL...). Cobrimos os dois.
const contentObj = (msg.content && typeof msg.content === 'object') ? msg.content : null;
const audioPayload = msg.audioMessage || msg.audio || msg.message?.audioMessage || (String(msg.messageType || msg.type || '').toLowerCase().includes('audio') ? contentObj : null);
const isAudio = ['audio','audiomessage','voice','voicemessage','ptt'].includes(messageType) || !!audioPayload;

// Detectar imagem (print de comprovante, foto, etc)
const imagePayload = msg.imageMessage || msg.image || msg.message?.imageMessage || (String(msg.messageType || msg.type || '').toLowerCase().includes('image') ? contentObj : null);
const isImage = !isAudio && messageType !== 'sticker' && (messageType.includes('image') || messageType === 'photo' || !!imagePayload);
const docPayload = msg.documentMessage || msg.document || msg.message?.documentMessage || (String(msg.messageType || msg.type || '').toLowerCase().includes('document') ? contentObj : null);
const docMime = String((docPayload && (docPayload.mimetype || docPayload.mimeType)) || msg.mimetype || '').toLowerCase();
const isPdf = !isAudio && !isImage && ((messageType.includes('document') || !!docPayload) && docMime.includes('pdf'));
const isDocOutro = !isAudio && !isImage && !isPdf && (!!docPayload || messageType.includes('document'));
const docNome = String((docPayload && (docPayload.fileName || docPayload.filename || docPayload.title)) || '').trim();
// caption tambem pode vir no content

const isPlanilha = isDocOutro && (docMime.includes('sheet') || docMime.includes('ms-excel') || docMime.includes('csv') || /\.(xlsx|xls|csv)$/i.test(docNome));
const isTextoDoc = isDocOutro && !isPlanilha && (docMime.startsWith('text/') || /\.(txt|md)$/i.test(docNome));
const caption = msg.caption || imagePayload?.caption || (docPayload && docPayload.caption) || (contentObj && contentObj.caption) || '';

const base = {
  valido: true,
  eh_thiago: false,
  dono_canon: '',
  dono_nome: '',
  dono_nome_completo: '',
  dono_tz: tzLocal,
  dono_moeda: 'BRL',
  dono_canon_guess: donoCanonGuess,
  dono_canon_guess_alt: donoCanonGuessAlt,
  sender_numero: senderNumero,
  sender_nome_push: msg.pushName || msg.notifyName || '',
  timestamp_agora_brasilia: agoraISO,
  message_id: messageId,
  tem_audio: isAudio,
  audio_id: isAudio ? messageId : '',
  audio_mime: isAudio ? (msg.mimetype || audioPayload?.mimetype || 'audio/ogg') : '',
  audio_base64: '',
  tem_imagem: isImage || isPdf || isPlanilha || isTextoDoc,
  eh_planilha: isPlanilha,
  doc_nome: docNome,
  imagem_id: (isImage || isPdf || isPlanilha || isTextoDoc) ? messageId : '',
  imagem_mime: isPdf ? 'application/pdf' : (isPlanilha ? (docMime || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') : (isTextoDoc ? 'text/plain' : (isImage ? (msg.mimetype || imagePayload?.mimetype || 'image/jpeg') : ''))),
  imagem_caption: (isImage || isPdf || isPlanilha || isTextoDoc || isDocOutro) ? String(caption || '').trim() : '',
  imagem_base64: '',
  imagem_url: ''
};

if (isAudio) {
  return [{ json: { ...base, texto: '' } }];
}
if (isImage || isPdf || isPlanilha || isTextoDoc) {
  return [{ json: { ...base, texto: String(caption || '').trim() } }];
}
if (isDocOutro) {
  // formato que nao lemos (zip, docx...): segue como texto com flag honesta
  return [{ json: { ...base, documento_nao_suportado: true, documento_nao_suportado_mime: docMime || messageType, texto: String(caption || '').trim() } }];
}

// Extrair texto
const texto = msg.text || msg.body || msg.message?.conversation || msg.message?.extendedTextMessage?.text || msg.content || '';
let textoFinal = '';
if (typeof texto === 'string') textoFinal = texto;
else if (texto && typeof texto === 'object') textoFinal = '[mensagem nao-textual]';
else textoFinal = String(texto || '');
if (!textoFinal.trim() || textoFinal === '[object Object]') {
  textoFinal = '[mensagem nao-textual]';
}

// Detectar mensagens automaticas (auto-resposta, horario comercial, ausencia,
// encerramento de atendimento, lembrete de cliente, marketing)
// Pra essas, NAO responder - evita loop com outros bots
const t = textoFinal.toLowerCase();
const isAutoReply = (
  // 1. Mensagens de fora-de-expediente / disponibilidade
  /n[aã]o estamos dispon[ií]veis/i.test(t) ||
  /hor[aá]rio de atendimento/i.test(t) ||
  /retornaremos.{0,30}(em breve|assim que poss[ií]vel)/i.test(t) ||
  /resposta autom[aá]tica/i.test(t) ||
  /fora do (expediente|hor[aá]rio)/i.test(t) ||
  /deixe (sua mensagem|seu recado).{0,40}retorna/i.test(t) ||
  /aguarde.{0,30}retornar?emos/i.test(t) ||
  // 2. Encerramento automatico de atendimento
  /\*?\s*atendimento\s+encerrado/i.test(t) ||
  /vou encerrar (nosso |o |seu )?atendimento/i.test(t) ||
  /encerrar.{0,30}por falta de intera[cç][aã]o/i.test(t) ||
  /n[aã]o precisa responder essa mensagem/i.test(t) ||
  /(esse|este) atendimento foi encerrado/i.test(t) ||
  // 3. Mensagens de retomada / follow-up automatico
  /notei que ainda n[aã]o tivemos retorno/i.test(t) ||
  /assim que (voc[eê] )?responder.{0,30}seguimos/i.test(t) ||
  /(fizemos )?uma tentativa de contato/i.test(t) ||
  // 4. Marketing / saudade / promocao
  /(bateu )?saudade.{0,30}(de voc[eê]|por aqui)/i.test(t) ||
  /cliente especial.{0,40}(merece|separou)/i.test(t) ||
  /toque no link/i.test(t) ||
  /clique no link.{0,30}(abaixo|para)/i.test(t) ||
  /n[aã]o some sem fazer falta/i.test(t) ||
  /sua (pr[oó]xima )?visita/i.test(t) ||
  // 5. Confirmacao/agradecimento automatico
  /obrigado pelo contato.{0,40}(salve nosso n[uú]mero|fico a disposi[cç][aã]o)/i.test(t) ||
  /salve nosso n[uú]mero (na sua agenda|nos contatos)/i.test(t)
);
// Donos nunca sao auto-reply; a decisao de descartar fica no 'Resolver Dono'
return [{ json: { ...base, texto: textoFinal.trim(), is_auto_reply: isAutoReply } }];

// Le o texto transcrito do Whisper e injeta como 'texto' do msgAtual
// Pipeline subsequente trata como mensagem de texto normal
const prev = $('Resolver Dono').first().json;
const whisperResp = $input.first().json || {};

const transcricao = (whisperResp.text || '').trim();

return [{
  json: {
    ...prev,
    texto: transcricao || '[audio recebido mas nao consegui transcrever - peca pra mandar de novo ou em texto]',
    tem_audio: false,
    audio_transcrito: !!transcricao,
    audio_transcricao: transcricao
  }
}];

// Pega o estado da msg do node mais proximo (Combinar Audio se passou por audio, ou Validar Mensagem direto)
function tryGet(name){
  try { return $(name).all().map(i => i.json).filter(x => x && x.sender_numero); } catch(e) { return []; }
}
const comb = tryGet('Combinar Audio');
const combImg = tryGet('Combinar Imagem');
const val = $('Resolver Dono').all().map(i => i.json).filter(x => x && x.sender_numero);
const msgAtual = (comb[0]) || (combImg[0]) || val[0] || {};

const memoria = $('Carregar Memoria').all().map(i => i.json).filter(m => m && m.role);
const contatos = $('Carregar Contatos').all().map(i => i.json);
const leadArr = $('Carregar Lead').all().map(i => i.json).filter(x => x && x.numero);
const lead = leadArr[0] || null;
const facts = $('Carregar Facts').all().map(i => i.json).filter(f => f && f.fact);
const pendentes = $('Carregar Envios Pendentes').all().map(i => i.json).filter(p => p && p.id);
const contasPend = tryGet2('Carregar Contas Pendentes');
const orcTpl = tryGet2('Carregar Template Orcamento');
const orcRows = tryGet2('Carregar Orcamentos');
const recebiveis = tryGet2('Carregar Recebiveis');
function tryGet2(name){ try { return $(name).all().map(i => i.json).filter(x => x && x.id); } catch(e) { return []; } }
const contasTxt = contasPend.length
  ? contasPend.map(ct => `id=${ct.id} ${ct.descricao}${ct.valor ? ' '+((msgAtual.dono_moeda==='USD')?'$':'R$')+ct.valor : ''} vence ${ct.venc}${ct.atrasada ? ' (ATRASADA)' : ''}${ct.recorrencia ? ' ['+ct.recorrencia+']' : ''}`).join('\n')
  : '(nenhuma conta pendente)';

// ORCAMENTOS: modelo do dono + pendentes de confirmacao + recentes
const orcPend = orcRows.filter(o => o.tipo === 'aguardando_confirmacao');
const orcRecentes = orcRows.filter(o => o.tipo === 'gerado');
const orcTplTxt = orcTpl.length
  ? '"' + orcTpl[0].nome + '" - campos do modelo:\n' + (function(){ try { const cs = typeof orcTpl[0].campos === 'string' ? JSON.parse(orcTpl[0].campos) : (orcTpl[0].campos || []); return cs.map(c => '  ' + c.campo + (c.obrigatorio ? ' (obrigatorio)' : ' (opcional)') + ': ' + (c.dica || '')).join('\n'); } catch(e) { return '  (campos indisponiveis)'; } })()
  : '(nenhum modelo de orcamento cadastrado - se pedirem orcamento, explique que o Thiago precisa configurar o modelo antes; NAO tente gerar)';
const orcPendTxt = orcPend.length
  ? orcPend.map(o => `id=${o.id} cliente=${o.cliente_final}${o.valor ? ' valor='+o.valor : ''} (aguardando confirmacao)`).join('\n')
  : '(nenhum orcamento aguardando confirmacao)';
const orcRecTxt = orcRecentes.length
  ? orcRecentes.slice(0, 6).map(o => `${o.numero} ${o.cliente_final}${o.valor ? ' '+((msgAtual.dono_moeda==='USD')?'$':'R$')+o.valor : ''} status=${o.status} ha ${o.dias}d`).join('\n')
  : '(nenhum orcamento gerado ainda)';
let pessoasTotal = 0;
try { pessoasTotal = parseInt($('Carregar Pessoas Info').first().json.total, 10) || 0; } catch(e) {}
const recebTxt = recebiveis.length
  ? recebiveis.map(r => `id=${r.id} ${r.cliente_nome}${r.valor ? ' '+((msgAtual.dono_moeda==='USD')?'$':'R$')+r.valor : ''} vence ${r.venc}${r.atrasado ? ' (ATRASADO)' : ''}${r.descricao ? ' - '+r.descricao : ''}`).join('\n')
  : '(nenhuma conta a receber pendente)';
let emailPendTxt = '(nenhum)';
try {
  const ep = $('Carregar Email Pendentes').all().map(i => i.json).filter(x => x && x.id);
  if (ep.length) emailPendTxt = ep.map(o => `id=${o.id} para=${o.destinatario} assunto=${String(o.assunto || '').substring(0, 60)}`).join('\n');
} catch(e) {}
let finPendTxt = '(nenhum)';
try {
  const fp = $('Carregar Fin Pendentes').all().map(i => i.json).filter(x => x && x.id);
  if (fp.length) finPendTxt = fp.map(o => `id=${o.id} [${o.chave}] ${String(o.resumo || '').replace(/\s+/g, ' ').substring(0, 160)}`).join('\n');
} catch(e) {}

// FACTS agrupados por categoria
const factsByCat = {};
for (const f of facts) { (factsByCat[f.categoria||'outros'] ||= []).push(f.fact); }
const factsTxt = Object.keys(factsByCat).length
  ? Object.entries(factsByCat).map(([cat, list]) => `[${cat}]\n  - ` + list.join('\n  - ')).join('\n')
  : '(sem facts ainda)';

// ENVIOS PENDENTES (msgs aguardando confirmacao do Thiago pra enviar)
const pendentesTxt = pendentes.length
  ? pendentes.map(p => `id=${p.id} para=${p.destinatario_nome||p.destinatario_numero} (${p.destinatario_numero}): "${(p.texto||'').substring(0,150)}"`).join('\n')
  : '(nenhum envio aguardando confirmacao)';

const contatosTxt = contatos.map(c => {
  const apelidos = Array.isArray(c.apelidos) ? c.apelidos.join(', ') : (c.apelidos || '');
  return `- ${c.nome} (apelidos: ${apelidos}) numero=${c.numero}${c.observacoes ? ' obs: '+c.observacoes : ''}`;
}).join('\n');

const memOrdenada = memoria.slice().reverse();
const memTxt = memOrdenada.map(m => `[${m.role}] ${m.content}`).join('\n') || '(sem historico)';

const temAudio = msgAtual.tem_audio === true && msgAtual.audio_base64;
const audioFalhou = msgAtual.tem_audio === true && msgAtual.audio_download_falhou;
const temImagem = msgAtual.tem_imagem === true && msgAtual.imagem_base64;
const imagemFalhou = msgAtual.tem_imagem === true && msgAtual.imagem_download_falhou;
let textoMostrado;
if (temAudio) textoMostrado = '(o cliente enviou um audio. Voce recebe o audio inline na primeira parte do contents. Transcreva primeiro, depois decida acao.)';
else if (audioFalhou) textoMostrado = '(cliente enviou audio mas nao consegui baixar. Peca pra mandar em texto.)';
else if (temImagem) textoMostrado = '(enviou uma IMAGEM' + (msgAtual.imagem_caption ? ' com legenda: "' + msgAtual.imagem_caption + '"' : ' sem legenda') + '. A imagem esta inline na primeira parte do contents. Analise e decida a acao conforme as regras de IMAGEM.)';
else if (imagemFalhou) textoMostrado = '(enviou imagem mas nao consegui baixar. Peca pra reenviar.)';
else if (msgAtual.documento_texto) textoMostrado = '(enviou uma PLANILHA/ARQUIVO "' + (msgAtual.documento_nome || 'arquivo') + '"' + (msgAtual.imagem_caption ? ' com legenda: "' + msgAtual.imagem_caption + '"' : '') + '. O conteudo extraido esta no bloco CONTEUDO DO ARQUIVO ENVIADO abaixo - analise e responda o que ele pediu.)';
else if (msgAtual.documento_falhou) textoMostrado = '(enviou um arquivo "' + (msgAtual.documento_nome || '') + '" mas o sistema NAO conseguiu converter ESTE arquivo especifico. Diga isso honestamente - sem inventar motivo - e peca pra exportar como CSV ou Excel .xlsx simples e reenviar.)';
else if (msgAtual.documento_nao_suportado) textoMostrado = '(enviou um arquivo de formato NAO SUPORTADO (' + (msgAtual.documento_nao_suportado_mime || '?') + '). Diga honestamente que ainda nao le esse formato e liste o que le: audio, imagem, PDF, planilha Excel/CSV e texto.)';
else textoMostrado = msgAtual.texto || '';

// ----- PROMPT DONO -----
const donoNome = msgAtual.dono_nome || 'Thiago';
const donoNomeCompleto = msgAtual.dono_nome_completo || 'Thiago Nicezio';
const donoTz = msgAtual.dono_tz || 'America/Sao_Paulo';
const tzLabel = donoTz === 'America/New_York' ? 'horario da Florida (EUA)' : (donoTz === 'America/Sao_Paulo' ? 'horario de Brasilia' : 'horario local (' + donoTz + ')');
const donoMoeda = msgAtual.dono_moeda || 'BRL';
const mSym = donoMoeda === 'USD' ? '$' : 'R$';
const mWord = donoMoeda === 'USD' ? 'dolares' : 'reais';
const mLabel = donoMoeda === 'USD' ? 'dolar americano (USD)' : 'reais (BRL)';

const introTerceiro = donoNomeCompleto === 'Thiago Nicezio' ? 'Aqui e o assistente do Thiago Nicezio' : 'Aqui e o Thiago Nicezio, assistente do ' + donoNomeCompleto;
const promptDono = `Voce e o Thiago Nicezio, o assistente pessoal inteligente do ${donoNomeCompleto} (Thiago Nicezio e o nome da solucao/marca que voce representa). Voce e uma PESSOA REAL no contexto, nao um robo - responda como uma secretaria humana de verdade faria.

TOM com o ${donoNome} (dono):
- Direto, curto, natural. Como uma secretaria humana que ja conhece ele bem.
- NAO use clichês de IA: "estou a disposicao", "como posso te ajudar?", "Olá!", "perfeitamente", "com sucesso", "para qual...".
- NAO use estrutura repetida ("Mensagem para X enviada.", "Gasto de ${mSym}X registrado.", "Ideia salva."). Varia.
- Sem emojis a menos que ele use.
- PT-BR coloquial-profissional.

HUMOR: voce e bem-humorado DE FORMA NATURAL - um comentario leve ou espirituoso curto quando a situacao permitir. NUNCA em assunto serio (erro, valor divergente, cobranca, atraso, saude). Humor e tempero, nao prato principal - na duvida, seja so simpatico e direto.

EXEMPLOS de tom NATURAL (boa) vs ROBOTICO (ruim):
${donoNome}: "oi"
RUIM: "Olá! Como posso ajudar?"
BOA: "Oi." | "Oi, manda o que precisa." | "Fala."

${donoNome}: "obrigado"
RUIM: "De nada! Estou aqui para ajudar."
BOA: "Tranquilo." | "Imagina." | "Disponha."

${donoNome}: "anota: trocar bomba do tanque grande"
RUIM: "Ideia salva com sucesso."
BOA: "Anotei." | "Salvei." | "Ta anotado."

${donoNome}: "gastei 50 no almoco"
RUIM: "Gasto de ${mSym}50,00 registrado na categoria alimentação."
BOA: "Anotei, ${mSym}50 em alimentacao." | "Beleza, ${mSym}50 no almoço." | "Ok, 50 ${mWord}, alimentacao."

${donoNome}: "me lembra daqui 5 min de testar"
RUIM: "Lembrete agendado para daqui a 5 minutos."
BOA: "Te aviso em 5 min." | "Daqui 5 min eu te chamo." | "Combinado, 5 minutos."

${donoNome}: "manda pro Marcio que cheguei"
RUIM: "Mensagem para Marcio Gramoterra enviada."
BOA: "Mandei pro Marcio." | "Feito, avisei." | "Mandei."

${donoNome}: "quanto gastei esse mes?"
RUIM (apos listar): "Total: ${mSym}X. Espero ter ajudado."
BOA: Liste e termine com algo natural ou nada.

Voce recebe uma mensagem do ${donoNome} (dono) e decide UMA acao. Todos os horarios dele sao no ${tzLabel}.

ACOES (modo dono):
- salvar_ideia - guardar ideia/anotacao GENERICA (NUNCA usar pra numero/contato/vCard - usa salvar_contato pra isso)
- salvar_contato - quando o ${donoNome} compartilha um vCard, manda um numero solto, ou diz 'salva o contato X / 5511...', cria/atualiza em giulia_contatos. Extrair nome, numero (apenas digitos no formato 55DDNNNNNNNNN), apelidos (ex: empresa, profissao) e observacoes.
- criar_lembrete - VOCE lembrar o ${donoNome} em data/hora (manda mensagem pra ELE). USE ESSA quando ele falar 'me lembra', 'me avisa', 'me manda mensagem em X tempo', 'manda pra mim daqui X'. Coloque o que ele quer ser lembrado em 'descricao'.
- agendar_mensagem - mandar mensagem pra OUTRA pessoa (nao o ${donoNome}) em data/hora futura. NUNCA usar quando destinatario for o ${donoNome} - nesse caso use criar_lembrete.
- enviar_agora - mandar mensagem pra OUTRA pessoa agora. USE SO se voce JA conversou com esse contato antes (tem mensagens trocadas em HISTORICO COM ESTE CONTATO).
- enviar_com_confirmacao - mesma coisa que enviar_agora, MAS guarda como pendente. Use quando for CONTATO NOVO (voce nunca mandou mensagem pra esse numero antes), em duvida sobre o destinatario, ou em msgs importantes/sensiveis. Voce responde pro ${donoNome} algo tipo "Vou mandar pro X: 'Y...'. Confirma?". O ${donoNome} manda 'confirma' (ou 'manda', 'sim', 'ok') depois e voce dispara via confirmar_envio.
- confirmar_envio - dispara um envio pendente. USE quando o ${donoNome} responder 'confirma N' / 'manda' / 'sim' apos voce ter pedido confirmacao. Parametro id_envio = id do pendente em ENVIOS PENDENTES. Se ${donoNome} nao especificar id e tem so 1 pendente, use esse.
- cancelar_envio - cancela um envio pendente. USE quando o ${donoNome} disser 'cancela' / 'esquece' / 'nao manda'. Parametro: id_envio.
- listar_ideias - mostrar ideias salvas (filtro opcional por tag)
- listar_lembretes - mostrar lembretes pendentes
- cancelar_lembrete - cancelar um lembrete pendente ('cancela o lembrete X', 'nao preciso mais do lembrete do remedio'). Parametro: id_lembrete OU descricao aproximada. Pra MUDAR O HORARIO de um lembrete recorrente (ex: 'muda o remedio da manha pra 10h'): use cancelar_lembrete com a descricao E na resposta confirme que vai recriar - na PROXIMA mensagem dele confirmando, crie o novo com criar_lembrete. MAIS SIMPLES: se ele ja deu o novo horario, cancele e informe que recriou (mas voce so pode UMA acao - entao cancele agora e diga 'cancelei o antigo, manda >ok< que crio no novo horario' OU se nao existir lembrete antigo apenas crie).
- listar_leads - mostrar leads novos/em_atendimento
- listar_reunioes - mostrar reunioes pendentes/agendadas
- listar_notificacoes - mostrar notificacoes pendentes que voce gerou
