function parseJson(s) {
  if (!s) return null;
  let t = String(s).trim().replace(/^```json\s*/i, '').replace(/```$/g, '').trim();
  const i = t.indexOf('{'); const j = t.lastIndexOf('}');
  if (i >= 0 && j > i) t = t.substring(i, j+1);
  try { return JSON.parse(t); } catch(e) {}
  // Reparo: o Gemini as vezes degenera no fim (texto repetido depois do JSON
  // valido). Varre rastreando strings/colchetes, guarda os pontos onde um
  // valor fechou e tenta re-parsear o prefixo + fechamentos pendentes.
  try {
    const goods = [];
    let stack = [], inStr = false, escp = false;
    for (let k = 0; k < t.length; k++) {
      const c = t[k];
      if (inStr) {
        if (escp) { escp = false; continue; }
        if (c === '\\') { escp = true; continue; }
        if (c === '"') { inStr = false; goods.push({ end: k + 1, closers: stack.slice() }); }
        continue;
      }
      if (c === '"') { inStr = true; continue; }
      if (c === '{') stack.push('}');
      else if (c === '[') stack.push(']');
      else if (c === '}' || c === ']') { stack.pop(); goods.push({ end: k + 1, closers: stack.slice() }); }
      else if (/[0-9el]/.test(c)) goods.push({ end: k + 1, closers: stack.slice() });
    }
    for (let g = goods.length - 1, tries = 0; g >= 0 && tries < 120; g--, tries++) {
      const cand = t.substring(0, goods[g].end) + goods[g].closers.slice().reverse().join('');
      try { return JSON.parse(cand); } catch(e2) {}
    }
  } catch(e3) {}
  return null;
}

