const RE_HORA_TAREFA = /(?:^|\s)[aà]s\s?(\d{1,2})(?:\s?h(?:([0-5]\d))?|\s?:\s?([0-5]\d))?(?=\s|$|,|\.|;)/i;
const auto_lembretes = [];
function lembreteAutoSql(tituloL, prazoParam) {
  try {
    const m = String(tituloL || '').match(RE_HORA_TAREFA);
    if (!m) return '';
    const hh = parseInt(m[1], 10);
    if (hh > 23) return '';
    const mm = parseInt(m[2] || m[3] || '0', 10);
    const tz = prev.dono_tz || 'America/Sao_Paulo';
    const hojeLocal = new Date().toLocaleDateString('sv-SE', { timeZone: tz });
    const data = (prazoParam && /^\d{4}-\d{2}-\d{2}/.test(String(prazoParam))) ? String(prazoParam).substring(0, 10) : hojeLocal;
    const tot = hh * 60 + mm - 20;
    if (tot < 0) return '';
    if (data === hojeLocal) {
      const agoraLocal = new Date().toLocaleTimeString('sv-SE', { timeZone: tz, hour12: false });
      const agoraMin = parseInt(agoraLocal.substring(0, 2), 10) * 60 + parseInt(agoraLocal.substring(3, 5), 10);
      if (tot <= agoraMin) return ''; // horario ja passou hoje: nao cria lembrete atrasado
    }
    const hq = String(Math.floor(tot / 60)).padStart(2, '0') + ':' + String(tot % 60).padStart(2, '0');
    const quando = data + ' ' + hq + ':00';
    const descL = String(tituloL).trim() + ' (em 20 min)';
    auto_lembretes.push({ titulo: String(tituloL).trim(), hora: hq });
    return "INSERT INTO giulia_lembretes (descricao, disparar_em, dono_numero) SELECT '" + esc(descL) + "', '" + quando + "'::TIMESTAMP, '" + esc(donoCanon) + "' WHERE NOT EXISTS (SELECT 1 FROM giulia_lembretes WHERE dono_numero = '" + esc(donoCanon) + "' AND descricao = '" + esc(descL) + "' AND disparar_em = '" + quando + "'::TIMESTAMP AND status = 'pendente');";
  } catch (e) { return ''; }
}

