    const perA = mEsp ? 'data' : (['hoje','amanha','semana','mes'].includes(String(p.periodo || '').toLowerCase()) ? String(p.periodo).toLowerCase() : 'hoje');
    const tzA = esc(prev.dono_tz || 'America/Sao_Paulo');
    let condA;
    if (perA === 'data') condA = `to_char(nascimento, 'MM-DD') = '${String(parseInt(mEsp[2], 10)).padStart(2, '0')}-${String(parseInt(mEsp[1], 10)).padStart(2, '0')}'`;
    else if (perA === 'hoje') condA = `to_char(nascimento, 'MM-DD') = to_char((NOW() AT TIME ZONE '${tzA}')::date, 'MM-DD')`;
    else if (perA === 'amanha') condA = `to_char(nascimento, 'MM-DD') = to_char((NOW() AT TIME ZONE '${tzA}')::date + 1, 'MM-DD')`;
    else if (perA === 'semana') condA = `to_char(nascimento, 'MM-DD') IN (SELECT to_char((NOW() AT TIME ZONE '${tzA}')::date + g, 'MM-DD') FROM generate_series(0, 6) g)`;
    else condA = `EXTRACT(MONTH FROM nascimento) = EXTRACT(MONTH FROM (NOW() AT TIME ZONE '${tzA}')::date)`;
    sql_query = `SELECT p.nome, to_char(p.nascimento, 'DD/MM') AS data, EXTRACT(YEAR FROM age((NOW() AT TIME ZONE '${tzA}')::date, p.nascimento))::int AS idade, COALESCE(p.grupo, '') AS grupo, COALESCE(p.numero, '') AS tel, COALESCE(p.familia, '') AS familia, COALESCE(tp.numero, '') AS tel_piloto FROM giulia_pessoas p LEFT JOIN LATERAL (SELECT p2.numero FROM giulia_pessoas p2 WHERE p2.dono_numero = p.dono_numero AND lower(p2.nome) = lower(p.familia) AND COALESCE(p2.numero, '') != '' LIMIT 1) tp ON true WHERE p.dono_numero = '${esc(donoCanon)}' AND p.nascimento IS NOT NULL AND ${condA.replace(/\bnascimento\b/g, 'p.nascimento')} ORDER BY p.nome LIMIT 60;`;
  } else if (acao === 'listar_gastos') {
    acao_tipo = 'DB_OP';
    const where = [];
    if (p.filtro_categoria) where.push(`(categoria ILIKE '${esc(p.filtro_categoria)}' OR subcategoria ILIKE '${esc(p.filtro_categoria)}')`);
    if (p.valor_min) where.push(`valor >= ${parseFloat(p.valor_min)}`);
    if (p.valor_max) where.push(`valor <= ${parseFloat(p.valor_max)}`);
    const periodoMap = { hoje: "data_gasto = CURRENT_DATE", semana: "data_gasto >= CURRENT_DATE - INTERVAL '7 days'", mes: "data_gasto >= date_trunc('month', CURRENT_DATE)", '30dias': "data_gasto >= CURRENT_DATE - INTERVAL '30 days'", ano: "data_gasto >= date_trunc('year', CURRENT_DATE)" };
    if (p.filtro_periodo && periodoMap[p.filtro_periodo]) where.push(periodoMap[p.filtro_periodo]);
    const whereSql = where.length ? 'WHERE ' + where.join(' AND ') : '';
    sql_query = `SELECT id, descricao, valor, categoria, subcategoria, forma_pagamento, data_gasto FROM giulia_gastos ${whereSql}${whereSql ? ' AND' : ' WHERE'} dono_numero = '${esc(donoCanon)}' ORDER BY data_gasto DESC, id DESC LIMIT 30;`;
  } else if (acao === 'resumo_gastos') {
    acao_tipo = 'DB_OP';
    const periodoMap = { hoje: "WHERE data_gasto = CURRENT_DATE", semana: "WHERE data_gasto >= CURRENT_DATE - INTERVAL '7 days'", mes: "WHERE data_gasto >= date_trunc('month', CURRENT_DATE)", '30dias': "WHERE data_gasto >= CURRENT_DATE - INTERVAL '30 days'", ano: "WHERE data_gasto >= date_trunc('year', CURRENT_DATE)" };
    const whereSql = (p.filtro_periodo && periodoMap[p.filtro_periodo]) ? periodoMap[p.filtro_periodo] : "WHERE data_gasto >= date_trunc('month', CURRENT_DATE)";
    sql_query = `SELECT COALESCE(categoria,'sem_categoria') AS categoria, COUNT(*) AS qtd, SUM(valor) AS total FROM giulia_gastos ${whereSql} AND dono_numero = '${esc(donoCanon)}' GROUP BY categoria ORDER BY total DESC;`;
  } else if (acao === 'editar_gasto') {
    const alvoEd = p.id_gasto ? `id = ${parseInt(p.id_gasto,10)}` : ((p.descricao_match || p.descricao) ? `id = (SELECT id FROM giulia_gastos WHERE dono_numero = '${esc(donoCanon)}' AND descricao ILIKE '%${esc(p.descricao_match || p.descricao)}%' ORDER BY id DESC LIMIT 1)` : null);
    if (!alvoEd) {
      acao = 'apenas_responder';
      dec.resposta = 'Qual gasto exatamente? Me da o nome ou o id dele.';
    } else {
    const sets = [];
    if (p.descricao) sets.push(`descricao = '${esc(p.descricao)}'`);
    if (numOuNull(p.valor) != null) sets.push(`valor = ${numOuNull(p.valor)}`);
    if (p.categoria) sets.push(`categoria = '${esc(p.categoria)}'`);
    if (p.subcategoria) sets.push(`subcategoria = '${esc(p.subcategoria)}'`);
    if (p.forma_pagamento) sets.push(`forma_pagamento = '${esc(p.forma_pagamento)}'`);
    if (p.data_gasto) sets.push(`data_gasto = '${esc(p.data_gasto.substring(0,10))}'::DATE`);
    if (p.observacoes) sets.push(`observacoes = '${esc(p.observacoes)}'`);
    if (sets.length > 0) {
      sets.push('sheets_synced = false');
      acao_tipo = 'DB_OP';
      sql_query = `UPDATE giulia_gastos SET ${sets.join(', ')} WHERE ${alvoEd} AND dono_numero = '${esc(donoCanon)}' RETURNING id, descricao, valor, categoria;`;
    } else {
      acao = 'apenas_responder';
      dec.resposta = 'O que voce quer mudar nesse gasto?';
    }
  }
  } else if (acao === 'deletar_gasto') {
    const alvoDel = p.id_gasto ? `id = ${parseInt(p.id_gasto,10)}` : ((p.descricao_match || p.descricao) ? `id = (SELECT id FROM giulia_gastos WHERE dono_numero = '${esc(donoCanon)}' AND descricao ILIKE '%${esc(p.descricao_match || p.descricao)}%' ORDER BY id DESC LIMIT 1)` : null);
    if (!alvoDel) {
      acao = 'apenas_responder';
      dec.resposta = 'Qual gasto voce quer apagar? Me da o nome ou o id.';
    } else {
      acao_tipo = 'DB_OP';
      sql_query = `DELETE FROM giulia_gastos WHERE ${alvoDel} AND dono_numero = '${esc(donoCanon)}' RETURNING id, descricao, valor;`;
    }
  }
} else {
  if (acao === 'qualificar_lead') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_leads (numero, nome, tipo_projeto, porte, localizacao, fase, resumo, status)
 VALUES ('${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, ${escOrNull(p.tipo_projeto)}, ${escOrNull(p.porte)}, ${escOrNull(p.localizacao)}, ${escOrNull(p.fase)}, ${escOrNull(p.resumo)}, 'em_atendimento')
 ON CONFLICT (numero) DO UPDATE SET
   nome = COALESCE(EXCLUDED.nome, giulia_leads.nome),
   tipo_projeto = COALESCE(EXCLUDED.tipo_projeto, giulia_leads.tipo_projeto),
   porte = COALESCE(EXCLUDED.porte, giulia_leads.porte),
   localizacao = COALESCE(EXCLUDED.localizacao, giulia_leads.localizacao),
   fase = COALESCE(EXCLUDED.fase, giulia_leads.fase),
   resumo = COALESCE(EXCLUDED.resumo, giulia_leads.resumo),
   status = CASE WHEN giulia_leads.status = 'novo' THEN 'em_atendimento' ELSE giulia_leads.status END,
   atualizado_em = NOW()
 RETURNING id, nome, tipo_projeto;
 INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia)
 SELECT 'lead_novo', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'Lead qualificado: ' || COALESCE(${escOrNull(p.tipo_projeto)}, '?') || ' / ' || COALESCE(${escOrNull(p.porte)}, '?') || ' / ' || COALESCE(${escOrNull(p.localizacao)}, '?') || E'\n' || COALESCE(${escOrNull(p.resumo)}, ''), 'normal'
 WHERE NOT EXISTS (SELECT 1 FROM giulia_notificacoes_thiago WHERE origem_numero = '${esc(senderNumero)}' AND tipo = 'lead_novo' AND status = 'pendente');`;
  } else if (acao === 'agendar_reuniao') {
    acao_tipo = 'DB_OP';
    // data exata eh OPCIONAL. Se cliente deu so janela aproximada ('quinta a tarde'),
    // salva NULL na data e poe a janela no assunto. Thiago confirma a data depois.
    const temData = p.agendado_para && /^\d{4}-\d{2}-\d{2}/.test(p.agendado_para);
    const dataSql = temData ? `'${esc(p.agendado_para)}'::TIMESTAMP` : 'NULL';
    const janela = p.janela_preferida || p.assunto_reuniao || '';
    const assuntoCompleto = [p.assunto_reuniao, janela && !p.assunto_reuniao ? null : (janela ? 'Disponibilidade: '+janela : null)].filter(Boolean).join(' | ') || janela;
    sql_query = `INSERT INTO giulia_leads (numero, nome, status) VALUES ('${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'agendado') ON CONFLICT (numero) DO UPDATE SET status = 'agendado', atualizado_em = NOW();
 INSERT INTO giulia_reunioes (lead_id, numero_cliente, nome_cliente, agendado_para, assunto, status)
 VALUES ((SELECT id FROM giulia_leads WHERE numero = '${esc(senderNumero)}'), '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, ${dataSql}, ${escOrNull(assuntoCompleto)}, 'pendente_aprovacao_thiago') RETURNING id, agendado_para;
 INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia)
 VALUES ('agendamento_pendente', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'Cliente quer conversar. Quando: ' || ${escOrNull(temData ? p.agendado_para : (janela || 'a combinar'))} || '. ' || COALESCE(${escOrNull(assuntoCompleto)}, '') || E'\nPra aprovar: aprovar reuniao <id>', ${escOrNull(p.urgencia || 'normal')});`;
  } else if (acao === 'notificar_thiago') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia) VALUES ('recado', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, '${esc(p.recado_thiago || dec.resposta || '')}', ${escOrNull(p.urgencia || 'normal')}) RETURNING id, resumo;`;
  } else if (acao === 'encaminhar') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia) VALUES ('encaminhamento', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'Encaminhei para ' || COALESCE(${escOrNull(p.encaminhar_para)}, '?') || ': ' || ${escOrNull(p.resumo || dec.resposta || '')}, 'info') RETURNING id;`;
  } else if (acao === 'marcar_engano') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_contatos_engano (numero, motivo) VALUES ('${esc(senderNumero)}', ${escOrNull(p.motivo_engano || 'numero errado/empresa diferente')}) ON CONFLICT (numero) DO UPDATE SET motivo = COALESCE(EXCLUDED.motivo, giulia_contatos_engano.motivo), expira_em = NOW() + INTERVAL '30 days', giulia_avisou = TRUE RETURNING numero;`;
  }
}

// Sanitizacao defensiva: remove auto-apresentacao redundante quando ja ha historico
function sanitizeApresentacao(texto, ehThiago, temHistoricoComContato) {
  if (ehThiago || !texto) return texto;
  if (!temHistoricoComContato) return texto;
  // Padroes a remover (so quando ja conversou antes)
  return texto
    .replace(/^(Olá!?|Oi[,!]?)?\s*(tudo\s+bem\??)?\s*(Aqui\s+[eé]|Sou)\s+o\s+(Thiago\s+Nicezio|assistente)[^.!\n]{0,60}[.!]\s*/i, '')
    .replace(/^(Olá!?\s*)?Sou\s+(a\s+)?Giulia\s+(Mascarenhas)?,?\s*(secret[aá]ria\s+(do|de)\s+Thiago\s+(Nicezio)?\.?\s*)?/gi, '')
    .replace(/^Oi[,!]?\s+(tudo\s+bem\?)?\s*Aqui\s+[eé]\s+(a\s+)?Giulia,?\s*(secret[aá]ria\s+(do|de)\s+Thiago\s+(Nicezio)?\.?\s*)?/gi, '')
    .replace(/Aqui\s+[eé]\s+(a\s+)?Giulia,?\s+secret[aá]ria\s+(do|de)\s+Thiago\s+(Nicezio)?\.?\s*/gi, '')
    .replace(/^[\s,\.!]+/, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Acoes extras na mesma mensagem (whitelist de inserts simples; prepend pra
// manter o RETURNING da acao principal como ultimo statement)
try {
  const extras = Array.isArray(dec.acoes_extras) ? dec.acoes_extras : [];
  const extrasSqls = [];
  for (const ax of extras.slice(0, 9)) {
    if (!ax || !ax.acao) continue;
    const q = ax.parametros || {};
    let s = '';
    if (ax.acao === 'registrar_gasto' && numOuNull(q.valor) != null) {
      const dg = dataValida(q.data_gasto) ? `'${esc(String(q.data_gasto).substring(0,10))}'::DATE` : ("(NOW() AT TIME ZONE '" + esc(prev.dono_tz || 'America/Sao_Paulo') + "')::date");
      s = `INSERT INTO giulia_gastos (descricao, valor, categoria, subcategoria, forma_pagamento, data_gasto, dono_numero) VALUES ('${esc(q.descricao || q.conteudo || 'gasto')}', ${numOuNull(q.valor)}, ${escOrNull(q.categoria)}, ${escOrNull(q.subcategoria)}, ${escOrNull(q.forma_pagamento)}, ${dg}, '${esc(donoCanon)}');`;
    } else if (ax.acao === 'criar_lembrete' && dataValida(q.disparar_em)) {
      s = `INSERT INTO giulia_lembretes (descricao, disparar_em, recorrencia, dono_numero) VALUES ('${esc(q.descricao || 'lembrete')}', '${esc(q.disparar_em)}'::TIMESTAMP, ${q.recorrencia ? `'${esc(q.recorrencia)}'` : 'NULL'}, '${esc(donoCanon)}');`;
    } else if (ax.acao === 'salvar_tarefa' && (q.titulo || q.descricao)) {
      const pz = q.prazo && /^\d{4}-\d{2}-\d{2}/.test(String(q.prazo)) ? `'${esc(String(q.prazo).substring(0,10))}'::DATE` : 'NULL';
      s = `INSERT INTO giulia_tarefas (titulo, prazo, proxima_cobranca_em, dono_numero) VALUES ('${esc(q.titulo || q.descricao)}', ${pz}, NOW() + INTERVAL '4 hours', '${esc(donoCanon)}');`;
      const laE = lembreteAutoSql(q.titulo || q.descricao, q.prazo);
      if (laE) s = s + '\n' + laE;
    } else if (ax.acao === 'registrar_conta' && numOuNull(q.valor) != null && q.vencimento && /^\d{4}-\d{2}-\d{2}/.test(String(q.vencimento))) {
      s = `INSERT INTO giulia_contas_pagar (descricao, valor, vencimento, recorrencia, dono_numero) VALUES ('${esc(q.descricao || 'conta')}', ${numOuNull(q.valor)}, '${esc(String(q.vencimento).substring(0,10))}'::DATE, ${q.recorrencia ? `'${esc(q.recorrencia)}'` : 'NULL'}, '${esc(donoCanon)}');`;
    } else if (ax.acao === 'cancelar_lembrete' && (q.id_lembrete || q.descricao_match || q.descricao)) {
      const alvoCL = q.id_lembrete ? `id = ${parseInt(q.id_lembrete,10)}` : `id = (SELECT id FROM giulia_lembretes WHERE dono_numero = '${esc(donoCanon)}' AND status = 'pendente' AND descricao ILIKE '%${esc(q.descricao_match || q.descricao)}%' ORDER BY id DESC LIMIT 1)`;
      s = `UPDATE giulia_lembretes SET status = 'cancelado' WHERE ${alvoCL} AND dono_numero = '${esc(donoCanon)}';`;
    } else if (ax.acao === 'marcar_tarefa_feita' && (q.id_tarefa || q.titulo_match || q.titulo)) {
      const alvoMF = q.id_tarefa ? `id = ${parseInt(q.id_tarefa, 10)}` : `id = (SELECT id FROM giulia_tarefas WHERE dono_numero = '${esc(donoCanon)}' AND status = 'pendente' AND titulo ILIKE '%${esc(q.titulo_match || q.titulo)}%' ORDER BY id DESC LIMIT 1)`;
      s = `UPDATE giulia_tarefas SET status = 'feita', feita_em = NOW() WHERE ${alvoMF} AND dono_numero = '${esc(donoCanon)}' AND status = 'pendente';`;
    } else if (ax.acao === 'adiar_tarefa' && (q.id_tarefa || q.titulo_match || q.titulo) && q.novo_prazo && /^\d{4}-\d{2}-\d{2}/.test(String(q.novo_prazo))) {
      const alvoAD = q.id_tarefa ? `id = ${parseInt(q.id_tarefa, 10)}` : `id = (SELECT id FROM giulia_tarefas WHERE dono_numero = '${esc(donoCanon)}' AND status = 'pendente' AND titulo ILIKE '%${esc(q.titulo_match || q.titulo)}%' ORDER BY id DESC LIMIT 1)`;
      s = `UPDATE giulia_tarefas SET prazo = '${esc(String(q.novo_prazo).substring(0,10))}'::DATE WHERE ${alvoAD} AND dono_numero = '${esc(donoCanon)}' AND status = 'pendente';`;
    } else if (ax.acao === 'salvar_ideia' && (q.conteudo || q.descricao)) {
      s = `INSERT INTO giulia_ideias (conteudo, dono_numero) VALUES ('${esc(q.conteudo || q.descricao)}', '${esc(donoCanon)}');`;
    }
    if (s) extrasSqls.push(s);
  }
  // extras executam na ORDEM da mensagem; principal fica por ultimo (RETURNING)
  if (extrasSqls.length) {
    if (acao_tipo === 'REPLY_ONLY') { acao_tipo = 'DB_OP'; sql_query = extrasSqls.join('\n'); }
    else if (acao_tipo === 'DB_OP') { sql_query = extrasSqls.join('\n') + '\n' + sql_query; }
  }
} catch(e) {}

// Verificar se ha historico com este contato (msgs em giulia_memoria com role=user dele)
let temHistoricoComContato = false;
try {
