    for (const r of rows) { porCat[r.categoria || 'outros'] = (porCat[r.categoria || 'outros'] || 0) + Number(r.valor || 0); }
    const catLinhas = Object.entries(porCat).sort((a,b) => b[1]-a[1]).map(([cat, v]) => `  ${cat}: ${fmtMoney(v)}`);
    const nLanc = rows.length === 1 ? '1 lancamento' : `${rows.length} lancamentos`;
