    const hojeStr = new Date().toLocaleDateString('sv-SE', { timeZone: (dec && dec.dono_tz) || $('Montar Prompt').first().json.dono_tz || 'America/Sao_Paulo' });
    const norm = rows.map(r => {
      const p = r.prazo ? String(r.prazo).substring(0, 10) : '';
      const mHora = String(r.titulo).match(/(?:^|\s)[a\u00e0]s\s?(\d{1,2})(?:\s?h(?:[0-5]\d)?|\s?:\s?[0-5]\d)?(?=\s|$|,|\.|;)/i);
      const hora = mHora ? parseInt(mHora[1], 10) : null;
      return { r, p, hora: (hora !== null && hora >= 0 && hora <= 23) ? hora : null };
    });
    const ordenadas = norm.filter(x => x.hora !== null).sort((a, b) => a.hora - b.hora)
      .concat(norm.filter(x => x.hora === null));
    const todasHoje = norm.every(x => x.p === hojeStr);
    const linhas = ordenadas.map((x, i) => {
      let sufixo = '';
      if (x.p && x.p !== hojeStr) sufixo = x.p < hojeStr ? ` — ATRASADA (era ${fmtDate(x.p)})` : ` — ate ${fmtDate(x.p)}`;
