      if (tp) linha += ` — ${tp}`;
      if (r.tel) linha += `\n     📱 ${fmtTelCrm(r.tel)}`;
      if (tp === 'Acompanhante' && r.familia) linha += `\n     👥 familia de ${r.familia}`;
      return linha;
    }).join('\n');
  }
}
if (acao === 'estatisticas_clientes') {
  const r = $input.first()?.json;
  if (r && r.total != null) {
    const semNasc = Number(r.total) - Number(r.com_nasc);
    textoResposta = `Tua base de clientes hoje:\n  ${r.total} cadastros\n  ${r.com_nasc} com data de nascimento` + (semNasc > 0 ? ` (${semNasc} SEM - nao aparecem nos aniversarios)` : '') + `\n  ${r.com_tel} com telefone\n  ${r.pilotos} pilotos · ${r.acompanhantes} acompanhantes · ${r.sem_tipo} sem tipo\n  ${r.familias} familias vinculadas` + ((semNasc > 0 || Number(r.com_tel) < Number(r.total) / 2) ? `\n\nPra completar os dados que faltam e so reenviar a planilha completa - agora eu ATUALIZO quem ja existe em vez de duplicar.` : '');
  }
}
if (acao === 'criar_expedicao') {
  const r = $input.first()?.json;
  if (r && r.id) textoResposta = `Expedicao criada: ${r.nome}${r.data ? ' — ' + r.data : ''}${r.vagas ? ' — ' + r.vagas + ' vagas' : ''} (#${r.id}). Pra inscrever: "inscreve fulano na ${r.nome}" (ou "a familia do fulano").`;
}
if (acao === 'listar_expedicoes') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.nome);
  if (!rows.length) textoResposta = 'Nenhuma expedicao cadastrada. Cria uma: "cria a expedicao X dia Y, N vagas".';
  else textoResposta = 'Expedicoes:\n' + rows.map(r => {
    let l = `  ${r.nome}${r.destino ? ' — ' + r.destino : ''}${r.data ? ' — ' + r.data : ''}`;
    if (r.data && r.dias_faltando > 0 && r.status === 'aberta') l += ` (faltam ${r.dias_faltando} dias)`;
    l += `\n     ${r.inscritos} inscrito(s)${r.vagas ? ' / ' + r.vagas + ' vagas' : ''} · ${r.pagos} pago(s)${r.status !== 'aberta' ? ' · ' + r.status : ''}`;
    return l;
  }).join('\n');
}
if (acao === 'inscrever_expedicao') {
  const r = $input.first()?.json;
  if (r) {
    if (!r.expedicao) textoResposta = 'Nao achei expedicao aberta com esse nome. "minhas expedicoes" mostra as que existem.';
    else if (Number(r.candidatos) === 0) textoResposta = 'Nao achei essa pessoa na tua base. Confere o nome ("procura o fulano" ajuda) ou cadastra antes.';
    else if (Number(r.candidatos) > 1) textoResposta = `Achei ${r.candidatos} pessoas com esse nome na base - me da o nome mais completo pra eu nao inscrever a errada.`;
    else if (Number(r.inscritos_agora) === 0) textoResposta = `Ja estava inscrito na ${r.expedicao}. Total: ${r.total_inscritos} inscrito(s)${r.vagas ? ' / ' + r.vagas + ' vagas' : ''}.`;
    else {
      textoResposta = `Inscrito(s) na ${r.expedicao}: +${r.inscritos_agora}. Total: ${r.total_inscritos}${r.vagas ? ' / ' + r.vagas + ' vagas' : ''}.`;
      if (r.vagas && Number(r.total_inscritos) >= Number(r.vagas)) textoResposta += ' ⚠️ LOTOU!';
      else if (r.vagas && Number(r.total_inscritos) >= Number(r.vagas) - 2) textoResposta += ` ⚠️ Restam so ${Number(r.vagas) - Number(r.total_inscritos)} vaga(s).`;
    }
  }
}
if (acao === 'lista_inscritos') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.expedicao);
  if (!rows.length) textoResposta = 'Nao achei expedicao aberta. "minhas expedicoes" lista as que existem.';
  else {
    const insc = rows.filter(r => r.pessoa_nome);
    const cab = `${rows[0].expedicao}${rows[0].data ? ' — ' + rows[0].data : ''}: ${insc.length} inscrito(s)${rows[0].vagas ? ' / ' + rows[0].vagas + ' vagas' : ''} · ${insc.filter(r => r.pago).length} pago(s)`;
    if (!insc.length) textoResposta = cab + '\nNinguem inscrito ainda.';
    else {
      const fmtTelE = t => { const d = String(t || '').replace(/\D/g, ''); if (!d) return ''; return d.length >= 12 ? '+' + d.substring(0, 2) + ' ' + d.substring(2, 4) + ' ' + d.substring(4, d.length - 4) + '-' + d.substring(d.length - 4) : t; };
      textoResposta = cab + '\n' + insc.map(r => `  ${r.pago ? '✅' : '⬜'} ${r.pessoa_nome}${r.tipo ? ' (' + r.tipo + ')' : ''}${r.tel ? ' — 📱 ' + fmtTelE(r.tel) : ''}`).join('\n');
    }
  }
}
if (acao === 'marcar_pago_expedicao') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.pessoa_nome);
  if (!rows.length) textoResposta = 'Nao achei esse inscrito nessa expedicao. "lista de inscritos" mostra quem ta la.';
  else textoResposta = 'Pagamento marcado ✅: ' + rows.map(r => r.pessoa_nome).join(', ');
}
if (acao === 'cancelar_inscricao') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.pessoa_nome);
  if (!rows.length) textoResposta = 'Nao achei esse inscrito pra cancelar.';
  else textoResposta = 'Inscricao cancelada: ' + rows.map(r => r.pessoa_nome).join(', ');
}
if (acao === 'cancelar_envio') {
  textoResposta = dec.resposta || 'Cancelado.';
}

// Fallback final: resposta nunca vazia
if (!textoResposta || !String(textoResposta).trim()) {
  const fb = {
    agendar_reuniao: 'Boa, vou ver a agenda do Thiago e te confirmo o horario. Qualquer coisa me chama.',
    qualificar_lead: 'Anotado. Vou passar pro Thiago e te retorno.',
    notificar_thiago: 'Passei pro Thiago, ele te responde.',
    encaminhar: 'Vou te direcionar com quem cuida disso.',
    apenas_responder: 'Certo.'
  };
  textoResposta = fb[acao] || 'Certo, anotado.';
}

try {
  const als = Array.isArray(dec.auto_lembretes) ? dec.auto_lembretes : [];
  if (als.length && !passoFalhou) {
    textoResposta += '\n' + als.map(a => '\u23f0 Te aviso ' + a.hora + ' (20 min antes): ' + a.titulo).join('\n');
  }
} catch (e) {}

return [{
  json: {
    sender_numero: dec.sender_numero,
    dono_canon: dec.dono_canon || '',
    texto_original: dec.texto_original,
    resposta_final: textoResposta,
    facts_novos: dec.facts_novos || [],
    envio_pendente_id: dec.envio_pendente_id || null,
    envio_falhou: passoFalhou,
    parse_falhou: dec.parse_falhou === true,
    eh_thiago: dec.eh_thiago === true,
    acao: dec.acao
  }
}];

// Monta SQL combinado: INSERT memoria + INSERT facts + UPDATE envio pendente
const frf = $('Formatar Resposta Final').first().json;
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");

const sender = frf.dono_canon || frf.sender_numero || '';
const texto_user = esc(frf.texto_original || '');
const resposta = esc(frf.resposta_final || '');
const facts_novos = Array.isArray(frf.facts_novos) ? frf.facts_novos : [];
const envio_id = frf.envio_pendente_id;
const acao = frf.acao || '';

let sql_parts = [];

// 1. Conversa
sql_parts.push(`INSERT INTO giulia_memoria (from_numero, role, content, metadata) VALUES ('${esc(sender)}', 'user', '${texto_user}', NULL), ('${esc(sender)}', 'assistant', '${resposta}', NULL);`);

// 2. Facts novos sobre o Thiago
for (const f of facts_novos) {
  if (!f || !f.fact) continue;
  const cat = f.categoria ? `'${esc(f.categoria)}'` : 'NULL';
  sql_parts.push(`INSERT INTO giulia_facts (about_numero, fact, categoria, fonte) VALUES ('${esc(sender)}', '${esc(f.fact)}', ${cat}, 'conversa') ON CONFLICT (about_numero, fact) DO UPDATE SET atualizado_em = NOW(), ativo = TRUE;`);
}

// 3. confirmar_envio: marca enviado OU erro conforme resultado real do envio
if (acao === 'confirmar_envio' && envio_id) {
  const st = frf.envio_falhou ? 'erro' : 'enviado';
  sql_parts.push(`UPDATE giulia_envios_pendentes SET status = '${st}', enviado_em = NOW() WHERE id = ${parseInt(envio_id,10)};`);
}

// 4. alerta tecnico pro Thiago quando falha em conversa de OUTRO dono (dedup 30 min)
if ((frf.parse_falhou || frf.envio_falhou) && frf.eh_thiago && sender !== '5511910441709') {
  const tipoAl = frf.parse_falhou ? 'IA respondeu fora do formato (mesmo apos retry)' : 'falha ao executar/entregar acao';
  const alerta = 'Alerta tecnico: ' + tipoAl + ' na conversa com ' + sender + '. Ultima resposta: ' + String(frf.resposta_final || '').substring(0, 90).replace(/'/g, '');
  sql_parts.push(`INSERT INTO giulia_mensagens_agendadas (destinatario_numero, destinatario_nome, conteudo, agendado_para, status) SELECT '5511910441709', 'Thiago', '\u26a0\ufe0f ${esc(alerta)}', NOW() AT TIME ZONE 'America/Sao_Paulo', 'pendente' WHERE NOT EXISTS (SELECT 1 FROM giulia_mensagens_agendadas WHERE destinatario_numero = '5511910441709' AND conteudo LIKE '\u26a0\ufe0f Alerta tecnico%' AND criado_em > NOW() - INTERVAL '30 minutes');`);
}

return [{
  json: {
    final_sql: sql_parts.join('\n')
  }
}];

// Se sender esta na tabela engano (ativo, nao expirou), IGNORA a msg.
// Marcar_engano ja avisa na 1a interacao (msg que disparou), entao todas as proximas sao ignoradas.
const engano = items.filter(i => i.json && i.json.numero);
if (engano.length > 0) {
  // Ja na tabela - corta o pipeline
  return [];
}
// Passa adiante o estado original
const prev = $('Validar Mensagem').first().json;
return [{ json: prev }];

// Anexa base64 + url da imagem ao estado da mensagem
const prev = $('Resolver Dono').first().json;
const urlResp = $('Baixar Imagem UAZAPI').first().json || {};
const current = $input.first().json || {};

if (current.planilha_texto !== undefined) {
  // planilha convertida em texto tabular (Spreadsheet File)
  return [{ json: {
    ...prev,
    tem_imagem: false,
    documento_texto: current.planilha_texto || '',
    documento_nome: prev.doc_nome || 'planilha',
    documento_linhas: current.planilha_linhas || 0,
    planilha_rows: current.planilha_rows || [],
    planilha_colunas: current.planilha_colunas || [],
    documento_falhou: !current.planilha_texto
  } }];
}
const b64 = current.imagem_b64_extraida || '';
const mime = urlResp.mimetype || prev.imagem_mime || 'image/jpeg';
const fileURL = urlResp.fileURL || '';

return [{
  json: {
    ...prev,
    imagem_base64: b64,
    imagem_mime: mime,
    imagem_url: fileURL,
    imagem_download_falhou: !b64
  }
}];

// Se o INSERT nao retornou row E a msg tem id, e um retry duplicado -> ignora
const prev = $('Validar Mensagem').first().json;
if (!prev.message_id) return [{ json: prev }]; // sem id, nao da pra dedupar - passa
const inserted = items.filter(i => i.json && i.json.message_id);
if (!inserted.length) return []; // duplicado - corta o pipeline
return [{ json: prev }];

// Resolve o dono via banco (cadastro dinamico) e recalcula timestamp no fuso dele
const base = $('Filtro Engano').first().json;
const row = ($input.first() && $input.first().json) || {};
const dono = row && row.numero ? row : null;
// auto-resposta de bot so e descartada se o remetente NAO e dono
if (base.is_auto_reply && !dono) return [];
const tz = dono ? (dono.timezone || 'America/Sao_Paulo') : 'America/Sao_Paulo';
const agoraISO = new Date().toLocaleString('sv-SE', { timeZone: tz }).substring(0, 19);
return [{ json: { ...base,
  eh_thiago: !!dono && String(dono.status || 'ativo') === 'ativo',
  dono_suspenso: !!dono && String(dono.status || 'ativo') !== 'ativo',
  dono_canon: dono ? String(dono.numero) : '',
  dono_nome: dono ? (dono.nome || '') : '',
  dono_nome_completo: dono ? (dono.nome_completo || dono.nome || '') : '',
  dono_tz: tz,
  dono_moeda: dono ? (dono.moeda || 'BRL') : 'BRL',
  timestamp_agora_brasilia: agoraISO
} }];

