// Linhas da planilha (Spreadsheet File) -> texto tabular capado pro prompt
// + TODAS as linhas (ate 6000) preservadas para importacao deterministica
const rows = items.map(i => i.json).filter(r => r && !r.error);
const MAXR = 400;
if (!rows.length) return [{ json: { planilha_texto: '', planilha_linhas: 0, planilha_rows: [], planilha_colunas: [] } }];
// uniao das chaves de TODAS as linhas: coluna vazia na 1a linha nao pode sumir
const colSet = new Set();
for (const r of rows) { for (const k of Object.keys(r)) colSet.add(k); }
const colunas = Array.from(colSet);
const linhas = rows.slice(0, MAXR).map(r =>
  colunas.map(c => String(r[c] == null ? '' : r[c]).replace(/[\n\r|]/g, ' ').trim()).join(' | '));
let texto = colunas.join(' | ') + '\n' + linhas.join('\n');
if (texto.length > 60000) texto = texto.substring(0, 60000) + '\n...(conteudo cortado)';
if (rows.length > MAXR) texto += `\n...(+${rows.length - MAXR} linhas omitidas NO TEXTO - mas a importacao via importar_planilha pega TODAS)`;
return [{ json: { planilha_texto: texto, planilha_linhas: rows.length, planilha_rows: rows.slice(0, 6000), planilha_colunas: colunas } }];

