const moedaFmt = v => 'R$ ' + Number(v).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
if (row.tipo_arte === 'capa') {
  camposA.expedicao = limpa(row.expedicao).substring(0, 34);
  camposA.destino = limpa(row.destino) || 'roteiro off-road';
  camposA.data_linha = (row.data ? row.data : 'data a definir') + (row.dias > 0 ? '  ·  faltam ' + row.dias + ' dias' : '');
  const dets = [];
  if (row.vagas) dets.push(row.vagas + ' vagas' + (row.inscritos ? ' (' + Math.max(0, row.vagas - row.inscritos) + ' livres)' : ''));
  if (row.valor != null && Number(row.valor) > 0) dets.push(moedaFmt(row.valor) + ' por pessoa');
