} else {
  camposA.pessoa = limpa(row.pessoa).substring(0, 40);
  camposA.expedicao = limpa(row.expedicao).substring(0, 44);
  camposA.data_linha = row.data ? 'Data: ' + row.data : 'Data a definir';
  camposA.status = row.pago ? 'INSCRICAO CONFIRMADA - PAGA' : 'RESERVADO - aguardando pagamento';
}
const pdf_b64 = buildOrcamentoPdf(layoutA, imagensA, camposA);
const slug = limpa(row.tipo_arte === 'capa' ? row.expedicao : row.pessoa).replace(/[^a-zA-Z0-9]+/g, '-').substring(0, 40) || 'arte';
const docName = (row.tipo_arte === 'capa' ? 'Expedicao-' : 'Voucher-') + slug + '.pdf';
const legenda = row.tipo_arte === 'capa'
  ? '🚙 Arte da ' + row.expedicao + ' pronta pra divulgar!'
  : '🎟️ Voucher de ' + row.pessoa + ' — ' + row.expedicao + '. E so encaminhar!';
return [{ json: { ok: true, pdf_b64, docName, legenda } }];
